#!/usr/bin/env node
// census-live-ownership.mjs — the push-condition ledger (V4-15). The user ruling (2026-10-16):
// git push happens only when truthsrc's output is byte-identical to the original codegen for
// EVERYTHING the engine generates; handwritten territory survives only as the declared
// isolation zone (sidecars/disclosures). This census makes that condition mechanical: every
// file under <live>/app + <live>/conf is classified by its `@generated by` stamp against the
// full-corpus identity ledger —
//
//   measured        a livePath the identity harness already compares (identical / owned-by-other)
//   reverse         a live file truthsrc does not emit, disclosed in reverseRows (handwritten 4 + relics)
//   stamped:<gen>   engine-stamped but NOT yet measured  → the must-generate backlog, by owner face
//   isolation       no stamp → handwritten candidate; subclassified:
//                     backup (.bak-*), conf (config/data), views (hand templates), handwritten (code)
//
// The census is an accounting tool, not a gate: it never reads generator output. Re-run after
// each porting increment; the `stamped` groups shrink toward zero and the isolation list is the
// whitelist that must stay honest. Scope: app/ + conf/ + test/ (test/ carries the tdd_test_gen
// stamped ExecutableSpec family).
//
// Output: golden/scala-cqrs-es-metarch/live-ownership-census.json (+ human summary to stdout).
//
// Usage: node tools/census-live-ownership.mjs [--live /path/to/ingested-app]
import { readdirSync, readFileSync, statSync, writeFileSync } from 'node:fs';
import { join, relative } from 'node:path';

const argLive = process.argv.includes('--live')
  ? process.argv[process.argv.indexOf('--live') + 1]
  : '/Users/zhongdj/Workspaces/ingested-app';
const LIVE = argLive;
const ID = JSON.parse(
  readFileSync(new URL('../golden/scala-cqrs-es-metarch/full-corpus.identity.json', import.meta.url), 'utf8'),
);
const measured = new Set(ID.rows.map((r) => r.livePath));
const reverse = new Set(ID.reverseRows.map((r) => r.livePath ?? r.path).filter(Boolean));

function walk(dir, out = []) {
  for (const n of readdirSync(dir)) {
    const p = join(dir, n);
    if (statSync(p).isDirectory()) walk(p, out);
    else out.push(p);
  }
  return out;
}

const STAMP_RX = /@generated by ([A-Za-z_][\w.]*)/;
const files = [...walk(join(LIVE, 'app')), ...walk(join(LIVE, 'conf')), ...walk(join(LIVE, 'test'))];
const groups = new Map();
const bump = (k, rel) => {
  if (!groups.has(k)) groups.set(k, []);
  groups.get(k).push(rel);
};

for (const f of files) {
  const rel = relative(LIVE, f);
  if (measured.has(rel)) { bump('measured', rel); continue; }
  if (reverse.has(rel)) { bump('reverse', rel); continue; }
  const m = rel.includes('.bak-') ? null : readFileSync(f, 'utf8').slice(0, 400).match(STAMP_RX);
  if (m) { bump(`stamped:${m[1]}`, rel); continue; }
  const cls = rel.includes('.bak-') ? 'backup'
    : rel.startsWith('conf/') ? 'conf'
    : rel.startsWith('app/views/') ? 'views'
    : rel.startsWith('test/') ? 'test'
    : 'handwritten';
  // V4-23 ruling groundwork (2026-10-16 user directive: separate scaffold/library from
  // generator-scope infra-config from genuinely handwritten app code): a second-axis
  // classification over the isolation bucket. Purely path-rule based; every isolation file
  // lands in exactly one class.
  const POLICY_DEAD = new Set([
    'app/net/imadz/metarch/application/projection/policy/PolicyOnApplyKnowledgePatchOnMergeCommittedHandler.scala',
    'app/net/imadz/metarch/application/projection/policy/PolicyOnConfirmPatchMergedOnPatchedHandler.scala',
    'app/net/imadz/metarch/application/projection/policy/PolicyOnEstablishConceptOnPatchedHandler.scala',
    'app/net/imadz/metarch/application/projection/policy/PolicyOnRecordConceptLandingsOnMergeCommittedHandler.scala',
  ]);
  let sub = cls;
  if (cls === 'handwritten') {
    if (POLICY_DEAD.has(rel)) sub = 'handwritten:relic-dead';
    else if (rel.startsWith('app/net/imadz/common/')) sub = 'handwritten:lib-framework';
    else if (rel.startsWith('app/net/imadz/infra/saga/')) sub = 'handwritten:lib-saga';
    else sub = 'handwritten:app';
  } else if (cls === 'conf') {
    if (rel === 'conf/projection.conf' || rel === 'conf/persistence.conf' || rel === 'conf/vector.conf' || rel === 'conf/sql/1.sql') sub = 'conf:generator-scope-infra';
    else if (rel.startsWith('conf/kb/')) sub = 'conf:kb-service';
    else if (rel.startsWith('conf/apimeta/')) sub = 'conf:contract-snapshot';
    else if (rel.startsWith('conf/sql/')) sub = 'conf:migration-ledger';
    else sub = 'conf:scaffold-app';
  } else if (cls === 'test') sub = 'test:app-handwritten';
  else if (cls === 'views') sub = 'views:scaffold';
  bump(`isolation:${sub}`, rel);
}

const total = { files: files.length };
// parent isolation:* groups aggregate their :subclasses — display-only (excluded from totals;
// files bump the leaf class only, so leaves already sum to the true isolation count)
const synthetic = new Set();
for (const [k, paths] of [...groups.entries()]) {
  const m = k.match(/^(isolation:[a-z]+):/);
  if (m) {
    if (!groups.has(m[1])) { groups.set(m[1], []); synthetic.add(m[1]); }
    groups.get(m[1]).push(...paths);
  }
}
const summary = {};
for (const [k, paths] of [...groups.entries()].sort()) {
  summary[k] = { count: paths.length, paths: paths.sort(), ...(synthetic.has(k) ? { displayOnly: true } : {}) };
  const m = k.match(/^stamped:(.+)$/);
  if (m) total[`mustGenerate:${m[1]}`] = (total[`mustGenerate:${m[1]}`] ?? 0) + paths.length;
}
total.mustGenerate = Object.entries(total)
  .filter(([k]) => k.startsWith('mustGenerate:'))
  .reduce((s, [, v]) => s + v, 0);
total.isolation = Object.entries(summary)
  .filter(([k]) => k.startsWith('isolation:') && !summary[k].displayOnly)
  .reduce((s, [, v]) => s + v.count, 0);

const out = {
  generatedAt: new Date().toISOString().slice(0, 10),
  live: LIVE,
  identity: 'golden/scala-cqrs-es-metarch/full-corpus.identity.json',
  identityGeneratedAt: ID.generatedAt,
  pushCondition: 'byte-identical for every stamped artifact; isolation zone is the only exemption',
  total,
  groups: summary,
};
const outPath = new URL('../golden/scala-cqrs-es-metarch/live-ownership-census.json', import.meta.url);
writeFileSync(outPath, JSON.stringify(out, null, 2) + '\n');

for (const [k, v] of Object.entries(total)) console.log(`${k}: ${v}`);
for (const [k, v] of Object.entries(summary)) console.log(`  ${k}: ${v.count}`);
